from __future__ import annotations

import ast
import base64
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]

BLOBS = {
    "DOCSTRINGS": "",
    "DUMP": "",
    "DIFFDUMP": "",
    "AUDIT": "",
    "TESTS": "",
    "PARSER_DUMP": "",
    "PARSER_DIFFDUMP": "",
    "RUN_DUMP": "",
    "RUN_DIFFDUMP": "",
    "GIT_DIFF_ADDITION": "",
    "ARCH_SYMBOL_BLOCK": "",
}


def blob(name: str) -> str:
    return base64.b64decode(BLOBS[name]).decode("utf-8")


def write(path: str, text: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text.strip("\n") + "\n", encoding="utf-8", newline="\n")


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def patch_constants() -> None:
    path = "src/codebase_lens/core/constants.py"
    text = read(path)
    if '"dump"' not in text:
        text = text.replace('    "doctor",\n    "snapshot",', '    "doctor",\n    "dump",\n    "snapshot",')
    if '"diffdump"' not in text:
        text = text.replace('    "diff",\n    "changed",', '    "diff",\n    "diffdump",\n    "changed",')
    write(path, text)


def patch_git_diff() -> None:
    path = "src/codebase_lens/git/diff.py"
    text = read(path)
    if "def collect_diff_between_refs" not in text:
        write(path, text.rstrip() + blob("GIT_DIFF_ADDITION") + "\n")


def patch_cli() -> None:
    path = "src/codebase_lens/cli.py"
    text = read(path)
    if "from codebase_lens.reports.dump import write_codebase_dump" not in text:
        text = text.replace("from codebase_lens.reports.diff import write_diff_reports\n", "from codebase_lens.reports.diff import write_diff_reports\nfrom codebase_lens.reports.diffdump import write_diffdump_reports\nfrom codebase_lens.reports.dump import write_codebase_dump\n")
    text = text.replace("from codebase_lens.git.diff import collect_changed_files\n", "from codebase_lens.git.diff import collect_changed_files, collect_diff_between_refs, collect_diff_patch\n")
    if 'sub.add_parser("dump"' not in text:
        anchor = '    doctor = sub.add_parser("doctor", parents=[parent], help="Validate local tool and repository readiness.")\n    doctor.set_defaults(handler=_run_doctor)\n\n'
        if anchor not in text:
            raise RuntimeError("Could not find doctor parser anchor in cli.py")
        text = text.replace(anchor, anchor + blob("PARSER_DUMP"), 1)
    if 'sub.add_parser("diffdump"' not in text:
        anchor = '    diff = sub.add_parser("diff", parents=[parent], help="Summarize Git diffs.")\n    diff.add_argument("--staged", action="store_true")\n    diff.add_argument("--unstaged", action="store_true")\n    diff.add_argument("--base")\n    diff.add_argument("--symbols", action="store_true")\n    diff.add_argument("--stat", action="store_true")\n    diff.set_defaults(handler=_run_diff)\n\n'
        if anchor not in text:
            raise RuntimeError("Could not find diff parser anchor in cli.py")
        text = text.replace(anchor, anchor + blob("PARSER_DIFFDUMP"), 1)
    if "def _run_dump(args: argparse.Namespace)" not in text:
        marker = "\ndef _run_tree(args: argparse.Namespace) -> int:\n"
        if marker not in text:
            raise RuntimeError("Could not find _run_tree insertion point in cli.py")
        text = text.replace(marker, blob("RUN_DUMP") + marker, 1)
    if "def _run_diffdump(args: argparse.Namespace)" not in text:
        marker = "\ndef _run_changed(args: argparse.Namespace) -> int:\n"
        if marker not in text:
            raise RuntimeError("Could not find _run_changed insertion point in cli.py")
        text = text.replace(marker, blob("RUN_DIFFDUMP") + marker, 1)
    write(path, text)


def patch_architecture() -> None:
    path = "src/codebase_lens/contracts/architecture.py"
    text = read(path)
    for item in ["src/codebase_lens/analyzers/docstrings.py", "src/codebase_lens/reports/dump.py", "src/codebase_lens/reports/diffdump.py", "scripts/dev/audits/audit_phase29_dump_diffdump.py"]:
        if f'"{item}"' not in text:
            text = text.replace('            "scripts/dev/audits/audit_phase28_manifest_consistency.py",', f'            "scripts/dev/audits/audit_phase28_manifest_consistency.py",\n            "{item}",')
    for symbol in ["_run_dump", "_run_diffdump"]:
        if f'"{symbol}"' not in text:
            text = text.replace('                    "_run_graph",', f'                    "_run_graph",\n                    "{symbol}",')
    if '"path": "src/codebase_lens/reports/dump.py"' not in text:
        marker = '"forbidden_imports": ['
        idx = text.find(marker)
        if idx < 0:
            raise RuntimeError("Could not find forbidden_imports marker in architecture.py")
        before, after = text[:idx], text[idx:]
        close_idx = before.rfind('],')
        if close_idx < 0:
            raise RuntimeError("Could not find required_symbols closing bracket in architecture.py")
        text = before[:close_idx] + blob("ARCH_SYMBOL_BLOCK") + before[close_idx:] + after
    write(path, text)


def assert_parses(paths: list[str]) -> None:
    for rel in paths:
        target = ROOT / rel
        try:
            ast.parse(target.read_text(encoding="utf-8"), filename=rel)
        except SyntaxError as exc:
            raise RuntimeError(f"Syntax error in {rel}: {exc}") from exc


def main() -> int:
    write("src/codebase_lens/analyzers/docstrings.py", blob("DOCSTRINGS"))
    write("src/codebase_lens/reports/dump.py", blob("DUMP"))
    write("src/codebase_lens/reports/diffdump.py", blob("DIFFDUMP"))
    write("scripts/dev/audits/audit_phase29_dump_diffdump.py", blob("AUDIT"))
    write("tests/test_dump_diffdump.py", blob("TESTS"))
    patch_constants()
    patch_git_diff()
    patch_cli()
    patch_architecture()
    assert_parses(["src/codebase_lens/analyzers/docstrings.py", "src/codebase_lens/reports/dump.py", "src/codebase_lens/reports/diffdump.py", "src/codebase_lens/git/diff.py", "src/codebase_lens/cli.py", "src/codebase_lens/contracts/architecture.py", "scripts/dev/audits/audit_phase29_dump_diffdump.py", "tests/test_dump_diffdump.py"])
    print("Slice 024 applied: source dump and Git range diffdump commands added.")
    print("The updater parsed every modified Python file before exiting.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
